<form method="get" class="card card-body mb-4"><div class="row g-3 align-items-end"><div class="col-md-7"><label for="q" class="form-label">Search experts</label><input class="form-control" name="q" id="q" value="{{ request('q') }}" placeholder="Name, organization or specialization" maxlength="150"></div><div class="col-md-3"><label class="form-label" for="type">Pool type</label><select class="form-select" name="type" id="type"><option value="">All types</option><option value="expert" @selected(request('type')==='expert')>Expert</option><option value="departmental" @selected(request('type')==='departmental')>Departmental Expert</option></select></div><div class="col-md-2 d-flex gap-2"><button class="btn btn-primary">Search</button><a class="btn btn-outline-secondary" href="{{ url()->current() }}">Clear</a></div></div></form>